content.code:
:root{
  --ink: #0d0d0d;
  --paper: #ffffff;
  --accent: #c6ff4a;
  --space: 8px;
  --radius: 24px;
}

.card{
  background: var(--paper);
  border-radius: var(--radius);
  padding: calc(var(--space) * 3);
  color: var(--ink);
}

const button = document.querySelector('.card button');

button?.addEventListener('click', () => {
  button.textContent = 'Reserved';
  button.disabled = true;
});

